/// <summary>A page of the publisher's list (only what the load needs).</summary>
public sealed record ReplicaPage<TRow>(IReadOnlyList<TRow> Items, int Total);

/// <summary>The publisher refused the request (authentication): retrying won't help.</summary>
internal sealed class ReplicaLoadException(string message) : Exception(message);

/// <summary>
/// Loads one replica: reads the publisher's pages, writes what is newer than the copy (an event may have brought
/// newer data already) and, when the list didn't change while it was read, removes what the publisher no longer has.
/// </summary>
public abstract class ReplicaLoader<TRow>(IServiceScopeFactory scopes, IHttpClientFactory httpClients, IConfiguration configuration, ILogger logger)
    : BackgroundService, IReplicaLoader
{
    private const int Attempts = 8;
    private readonly SemaphoreSlim running = new(1, 1);

    public abstract string Publisher { get; }

    public abstract string Entity { get; }

    /// <summary>The publisher's name in Aspire (services:&lt;resource&gt;:http:0).</summary>
    protected abstract string Resource { get; }

    /// <summary>Route segment of the entity in the publisher (/api/v1/&lt;route&gt;).</summary>
    protected abstract string Route { get; }

    protected abstract Guid IdOf(TRow row);

    protected abstract Task<bool> HasRowsAsync(IServiceProvider services, CancellationToken cancellationToken);

    /// <summary>Writes the rows newer than the copy; returns how many it wrote.</summary>
    protected abstract Task<int> UpsertAsync(IServiceProvider services, IReadOnlyList<TRow> rows, CancellationToken cancellationToken);

    /// <summary>Removes the copies not in <paramref name="kept"/> whose last change is older than <paramref name="before"/>.</summary>
    protected abstract Task<int> RemoveAsync(IServiceProvider services, IReadOnlySet<Guid> kept, DateTimeOffset before, CancellationToken cancellationToken);

    private string Name => Entity + "Replica";

    public override void Dispose()
    {
        running.Dispose();
        base.Dispose();
        GC.SuppressFinalize(this);
    }

    public async Task<ReplicaLoadResult> LoadAsync(CancellationToken cancellationToken)
    {
        var address = ReplicaLoading.Address(configuration, Publisher, Resource);
        if (address is null)
        {
            return new ReplicaLoadResult(Name, 0, 0, 0,
                $"This service doesn't know where {Publisher} is: reference it from the AppHost (WithReference) or set Replicas:{Publisher}:Url.");
        }

        await running.WaitAsync(cancellationToken);
        try
        {
            return await ReadAllAsync(address, cancellationToken);
        }
        catch (ReplicaLoadException ex)
        {
            return new ReplicaLoadResult(Name, 0, 0, 0, ex.Message);   // refused (authentication): retrying won't help
        }
        finally
        {
            running.Release();
        }
    }

    private async Task<ReplicaLoadResult> ReadAllAsync(Uri address, CancellationToken cancellationToken)
    {
        for (var attempt = 1; ; attempt++)
        {
            var started = DateTimeOffset.UtcNow;
            var seen = new HashSet<Guid>();
            var (read, written, total, stable) = (0, 0, -1, true);
            var http = httpClients.CreateClient(ReplicaLoading.HttpClientName);
            for (var page = 1; ; page++)
            {
                var result = await PageAsync(http, address, page, cancellationToken);
                stable &= total < 0 || result.Total == total;
                total = result.Total;
                if (result.Items.Count == 0)
                {
                    break;
                }

                foreach (var row in result.Items)
                {
                    seen.Add(IdOf(row));
                }

                read += result.Items.Count;
                await using (var scope = scopes.CreateAsyncScope())
                {
                    written += await UpsertAsync(scope.ServiceProvider, result.Items, cancellationToken);
                }

                if (read >= result.Total)
                {
                    break;
                }
            }

            if (!stable && attempt < 3)
            {
                continue;   // rows were created or deleted while reading: the pages may have shifted, read them again
            }

            var removed = 0;
            if (stable)
            {
                await using var scope = scopes.CreateAsyncScope();
                removed = await RemoveAsync(scope.ServiceProvider, seen, started, cancellationToken);
            }

            logger.LogInformation("Replica {Replica} loaded from {Publisher}: {Read} read, {Written} written, {Removed} removed", Name, Publisher, read, written, removed);
            return new ReplicaLoadResult(Name, read, written, removed, stable ? null
                : $"{Publisher} kept changing while it was read: nothing was removed. Load it again later.");
        }
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var when = (configuration[$"Replicas:{Publisher}:Load"] ?? configuration["Replicas:Load"] ?? "empty").Trim().ToLowerInvariant();
        if (when == "never" || ReplicaLoading.Address(configuration, Publisher, Resource) is null)
        {
            return;   // turned off, or this service doesn't know where the publisher is (tests, a run without the AppHost)
        }

        try
        {
            for (var attempt = 1; attempt <= Attempts; attempt++)
            {
                try
                {
                    if (when != "always")
                    {
                        await using var scope = scopes.CreateAsyncScope();
                        if (await HasRowsAsync(scope.ServiceProvider, stoppingToken))
                        {
                            return;   // loaded already: the events keep it up to date
                        }
                    }

                    var result = await LoadAsync(stoppingToken);
                    if (result.Problem is not null)
                    {
                        logger.LogWarning("Replica {Replica}: {Problem}", Name, result.Problem);
                    }

                    return;
                }
                catch (Exception ex) when (ex is not OperationCanceledException && attempt < Attempts)
                {
                    var delay = TimeSpan.FromSeconds(Math.Min(60, 2 << attempt));
                    logger.LogInformation(ex, "Replica {Replica}: {Publisher} not ready yet, trying again in {Delay}", Name, Publisher, delay);
                    await Task.Delay(delay, stoppingToken);
                }
            }
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
