        catch (Exception ex)
        {
            // Never stop the service for this: the replica fills with the events, and it can be loaded again later.
            logger.LogError(ex, "Replica {Replica} could not be loaded from {Publisher}", Name, Publisher);
        }
    }

    private async Task<ReplicaPage<TRow>> PageAsync(HttpClient http, Uri address, int page, CancellationToken cancellationToken)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get, new Uri(address, $"/api/v1/{Route}?page={page}&pageSize={ReplicaLoading.PageSize}"));
        if (configuration[$"Replicas:{Publisher}:Authorization"] is { Length: > 0 } authorization)
        {
            request.Headers.TryAddWithoutValidation("Authorization", authorization);
        }

        using var response = await http.SendAsync(request, cancellationToken);
        if (response.StatusCode is HttpStatusCode.Unauthorized or HttpStatusCode.Forbidden)
        {
            throw new ReplicaLoadException(
                $"{Publisher} answered {(int)response.StatusCode} to GET /api/v1/{Route}: set Replicas:{Publisher}:Authorization to the header to send (\"Bearer ...\").");
        }

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ReplicaPage<TRow>>(ReplicaLoading.Json, cancellationToken)
               ?? throw new InvalidOperationException($"{Publisher} answered GET /api/v1/{Route} without a body.");
    }
